Subroutine Suspendable Measure(sensor As Channel<Integer>)
  For measurement <- 1 To 5 Do
    Define temperature As Integer;
    Read temperature;
    Define accepted As Boolean <- Await sensor.send(temperature);
    If Not accepted Then
      Write "The sensor disconnected";
    EndIf
  EndFor
  sensor.close();
EndSubroutine

Subroutine Suspendable Average(sensor As Channel<Integer>)
  Define sum As Integer <- 0;
  Define measurements As Integer <- 0;
  Repeat
    Switch Await sensor.receive() Do
      Some(temperature):
        sum <- sum + temperature;
        measurements <- measurements + 1;
      None: Break;
    EndSwitch
  Until False
  Write sum / measurements;
EndSubroutine

Algorithm Sensor
  Define sensor As Channel<Integer> <- channel(2);
  Tasks
    Spawn Measure(sensor);
    Spawn Average(sensor);
  EndTasks
EndAlgorithm
